WFJ.Data.add("spell", {
  [426175] = { "Incidi sulla tua cintura la runa Malleable Protection:\n\n$I1\nOra puoi agire durante Protezione Divina e la sua durata aumenta del $N1%, ma invece di renderti immune riduce solo del $N2% i danni che subisci. Inoltre, attivare Scudo Benedetto ti fornisce anche $N3 potenza d'attacco per ogni punto della tua abilità in difesa oltre $N4, per $D1.", nil, 0x523ac40a, nil, "um" },
  [426180] = { "Incidi sulla tua cintura la runa Infusione di Luce:\n\n$I1\nI critici di Folgore Sacra e Lampo di Luce riducono di $D2 il tempo di lancio del tuo prossimo Luce Sacra entro $D1.", nil, 0x4905da9b, nil, "um" },
  [426359] = { "Decifra gli appunti dell'incantesimo con un Comprehension Charm per apprendere un nuovo incantesimo d'incisione.", nil, 0x7ccaad21, nil, "um" },
  [426443] = { "Incidi sulla tua cintura la runa Invocation:\n\n$I1\nApplicare Corruzione, Immolazione, Maledizione dell'Agonia, Afflizione Instabile, Ombrofuoco o Aspirazione della Vita ti fa infliggere istantaneamente al bersaglio danni pari a un impulso dei danni periodici dell'incantesimo. Rinnovare uno di questi incantesimi quando gli restano meno di $N1 s di durata ti fa infliggere istantaneamente al bersaglio danni pari ai danni periodici rimanenti dell'incantesimo.", nil, 0xf02be364, nil, "um" },
  [426445] = { "Incidi sulla tua cintura la runa Rito della Sinergia:\n\n$I1\nI danni inflitti da te o dal demone che hai evocato hanno il $N1% di probabilità di aumentare del $N2% i danni inflitti dall'altro per $D1.", nil, 0x6962f950, nil, "um" },
  [426452] = { "Incidi sulla tua cintura la runa Ombra e Fiamma:\n\n$I1\nColpire un nemico con Conflagrazione aumenta del $N1% tutti i danni da ombra che infliggi per $D1, e colpire un nemico con Combustione dell'Ombra aumenta del $N3% tutti i danni da fuoco che infliggi per $D2. Inoltre, Conflagrazione ha il $N5% di probabilità di non consumare Immolazione, e Combustione dell'Ombra ha il $N6% di probabilità di restituirti istantaneamente un Soul Shard.", nil, 0x6e71e40a, nil, "um" },
  [426467] = { "Incidi sui tuoi stivali la runa Ombrofuoco:\n\n$I1\nBrucia il nemico infliggendo $N1 danni da ombrofuoco e poi altri $N2 danni da ombrofuoco in $D1.\n\nOmbrofuoco attiva e beneficia di tutti gli effetti che modificano Immolazione o interagiscono con essa, o con gli incantesimi di Afflizione, Distruzione, fuoco od ombra, ma su un bersaglio può essere attivo un solo Immolazione od Ombrofuoco per Stregone. Inoltre, Ombrofuoco può attivare il tuo talento Dardo d'Ombra Migliorato e gli fa ottenere $N4 cariche aggiuntive.", nil, 0xc47d2fb0, nil, "um" },
  [426470] = { "Incidi sul tuo elmo la runa Vendetta:\n\n$I1\nQuando viene attivata, questa abilità aumenta temporaneamente del $N1% la tua salute massima per $D1. Quando l'effetto termina, la salute aggiuntiva va perduta. Inoltre, durante Metamorfosi, Vendetta fa sì che le tue ali rallentino la tua caduta.", nil, 0xb6b931d6, nil, "um" },
  [426491] = { "Incidi sui tuoi stivali la runa Chiamata a Raccolta:\n\n$I1\nLancia un grido di raccolta che aumenta del $N2% la salute massima di tutti i membri del gruppo e dell'incursione entro $N1 m per $D1.", nil, 0xec8cc0d9, nil, "um" },
  [426668] = { "Evoca $N1 Stone Rumblers che affiancano l'incantatore fino al congedo.", nil, 0x36bf232d, nil, "um" },
})
